#!/bin/bash
# Generated by tools/aether_train_run.py for run qwen38-27b-l1-pilot; do not edit by hand.
# Serves each variant, smoke-tests it on 3 easy tasks, then scores every
# suite with --resume. Re-run to continue; finished suites have a .done marker.
set -u
R=$HOME/aether-train/qwen38-27b-l1-pilot
B=$HOME/aether-train/qwen38-27b-l1-pilot/bench
OUT="$R/score"
LOG="$OUT/score.log"
GRADER=$HOME/aether-current/build/aether
mkdir -p "$OUT"
log() { echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] $*" | tee -a "$LOG"; }
cleanup() { docker rm -f aether-serve-qwen38-27b-l1-pilot >/dev/null 2>&1; log "served model stopped"; }
trap cleanup EXIT

[ -x "$GRADER" ] || { log "ABORT grader missing: $GRADER"; exit 2; }
GRADER_VERSION=$($GRADER --version 2>&1 | head -1)
GRADER_SHA=$(sha256sum "$GRADER" | cut -d' ' -f1)
log "grader $GRADER_VERSION sha256 $GRADER_SHA"
case "$GRADER_VERSION" in *2026-10-15-2*) ;; *) log "ABORT grader is not language 2026-10-15-2"; exit 2 ;; esac
echo "$GRADER_SHA" > "$OUT/grader.sha256"

serve() {
  docker rm -f aether-serve-qwen38-27b-l1-pilot >/dev/null 2>&1
  case "$1" in
    tuned) docker run -d --name aether-serve-qwen38-27b-l1-pilot --gpus all --ipc=host --shm-size=16g -v /storage:/storage -p 8019:8000 vllm/vllm-openai:latest --model /storage/aether-train/qwen38-27b-l1-pilot/merged_16bit --served-model-name qwen38-27b-l1-pilot-tuned --dtype bfloat16 --max-model-len 32768 --gpu-memory-utilization 0.85 --port 8000 --enforce-eager ;;
  esac
}

for VARIANT in tuned; do
  KIND=${VARIANT%%:*}; DOCS=none
  case "$VARIANT" in *:*) DOCS=${VARIANT#*:} ;; esac
  TAGV=${VARIANT//:/-}
  # Done when every suite of the current plan is done (suites may be added later).
  PENDING=0
  for PAIR in v2_pos=Tests/aether_doc_bench/tasks_v2_pos.json hard_v2=Tests/aether_doc_bench/tasks_hard_v2.json hard_nontoon=Tests/aether_doc_bench/tasks_hard_nontoon.json cs=Tests/aether_doc_bench/tasks_cs.json frontier=Tests/aether_doc_bench/tasks_frontier.json frontier_algo=Tests/aether_doc_bench/tasks_frontier_algo.json frontier_spec=Tests/aether_doc_bench/tasks_frontier_spec.json sealed_toon=Tests/aether_doc_bench/tasks_sealed_toon.json; do [ -f "$OUT/${TAGV}__${PAIR%%=*}.done" ] || PENDING=1; done
  [ $PENDING -eq 0 ] && { log "SKIP $VARIANT (every suite done)"; continue; }
  if [ "$KIND" = tuned ] && [ ! -f /storage/aether-train/qwen38-27b-l1-pilot/merged_16bit/config.json ]; then log "SKIP $VARIANT: no merged export yet"; continue; fi
  NAME=qwen38-27b-l1-pilot-$KIND
  log "=== $VARIANT: serving $NAME"
  serve "$VARIANT" >> "$LOG" 2>&1 || { log "FAIL docker run for $VARIANT"; continue; }
  READY=0
  for i in $(seq 1 180); do
    curl -s --max-time 5 http://localhost:8019/v1/models 2>/dev/null | grep -q "\"$NAME\"" && { READY=1; break; }
    [ "$(docker inspect -f '{{.State.Running}}' aether-serve-qwen38-27b-l1-pilot 2>/dev/null)" = "true" ] || break
    sleep 10
  done
  if [ $READY -ne 1 ]; then log "FAIL $VARIANT never became ready"; docker logs --tail 80 aether-serve-qwen38-27b-l1-pilot >> "$LOG" 2>&1; continue; fi
  log "READY $VARIANT"
  DEST="$R/destinations.$KIND.json"
  run_suite() {  # name tasks repeats repairs
    EXTRA=""
    case " frontier " in *" $1 "*) EXTRA="--allow-broken-oracle" ;; esac
    python3 -u "$B/tools/aether_doc_bench.py" --destinations-config "$DEST" --tasks "$2" $EXTRA \
      --docs "$DOCS" --repeats "$3" --repair-attempts "$4" --seed-base 42 \
      --aether-bin "$GRADER" --aether-bin-sha256 "$GRADER_SHA" --allow-skew --keep-loaded \
      --resume --output-json "$OUT/${TAGV}__$1.json" --text-summary >> "$LOG" 2>&1
  }
  if [ ! -f "$OUT/${TAGV}__smoke.ok" ]; then
    run_suite smoke "$R/smoke_tasks.json" 1 0
    if ! python3 "$R/check_generations.py" "$OUT/${TAGV}__smoke.json" '["thinking", "<think", "okay, "]' >> "$LOG" 2>&1; then
      log "FAIL $VARIANT smoke: empty output or a reasoning trace; not scoring it"; continue
    fi
    touch "$OUT/${TAGV}__smoke.ok"
  fi
  ALL=1
  for PAIR in v2_pos=Tests/aether_doc_bench/tasks_v2_pos.json hard_v2=Tests/aether_doc_bench/tasks_hard_v2.json hard_nontoon=Tests/aether_doc_bench/tasks_hard_nontoon.json cs=Tests/aether_doc_bench/tasks_cs.json frontier=Tests/aether_doc_bench/tasks_frontier.json frontier_algo=Tests/aether_doc_bench/tasks_frontier_algo.json frontier_spec=Tests/aether_doc_bench/tasks_frontier_spec.json sealed_toon=Tests/aether_doc_bench/tasks_sealed_toon.json; do
    SUITE=${PAIR%%=*}; TASKS="$B/${PAIR#*=}"
    [ -f "$OUT/${TAGV}__$SUITE.done" ] && continue
    log "--- $VARIANT $SUITE"
    run_suite "$SUITE" "$TASKS" 1 2
    if python3 "$R/check_generations.py" "$OUT/${TAGV}__$SUITE.json" '["thinking", "<think", "okay, "]' --complete >> "$LOG" 2>&1; then
      touch "$OUT/${TAGV}__$SUITE.done"
    else
      ALL=0; log "WARN $VARIANT $SUITE incomplete or suspicious; re-run to resume"
    fi
  done
  [ $ALL -eq 1 ] && touch "$OUT/$TAGV.done" && log "DONE $VARIANT"
  docker rm -f aether-serve-qwen38-27b-l1-pilot >/dev/null 2>&1
done
log "score pass finished"
